"""Generate static bilingual portfolio and resume from confirmed shared content. Python 3, no dependencies."""
from pathlib import Path
import json
from html import escape as e
ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'data/profile.json').read_text())
def esc(s): return e(str(s),quote=True)
def tags(items): return '<ul class="tags">'+''.join('<li>'+esc(x)+'</li>' for x in items)+'</ul>'
def para(items): return ''.join('<p>'+esc(x)+'</p>' for x in items)
def experience(): return ''.join('<article class="timeline-item"><span class="eyebrow">'+esc(x[2])+'</span><h3>'+esc(x[0])+'</h3><p class="organization">'+esc(x[1])+'</p><p>'+esc(x[3])+'</p></article>' for x in d['experience'])
def education(): return ''.join('<article class="panel"><h3>'+esc(x[0])+'</h3><p>'+esc(x[1])+'</p><p class="muted">'+esc(x[2])+'</p></article>' for x in d['education'])
def skills(): return ''.join('<article class="panel"><h3>'+esc(k)+'</h3>'+tags(v)+'</article>' for k,v in d['skills'].items())
def projects(fi=False):
 out=''
 for i,p in enumerate(d['projects']):
  name,status,role,description,stack,features,links=p
  media='<div class="project-visual" role="img" aria-label="'+esc(name)+' project identity placeholder"><span class="visual-number">0'+str(i+1)+'</span><strong>'+esc(name)+'</strong><span>'+('Projektin kuvitus · ei kuvakaappaus' if fi else 'Project identity · screenshot pending')+'</span></div>'
  out+='<article class="project panel" id="project-'+str(i+1)+'">'+media+'<div class="project-copy"><span class="status">'+esc(status)+'</span><h3>'+esc(name)+'</h3><p class="organization">'+esc(role)+'</p><p>'+esc(description)+'</p>'+tags(stack)
  if features: out+='<details><summary>'+('Projektin tiedot' if fi else 'Project details')+'</summary><ul>'+''.join('<li>'+esc(x)+'</li>' for x in features)+'</ul></details>'
  out+='<div class="project-links">'+''.join('<a href="'+esc(url)+'">'+esc(label)+' ↗</a>' for label,url in links)+'</div></div></article>'
 return out

def head(lang,title,description,path):
 return '<!doctype html>\n<html lang="'+lang+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(description)+'"><meta name="theme-color" content="#101927"><link rel="icon" href="favicon.ico"><link rel="canonical" href="https://esirioneyibo.github.io/'+path+'"><link rel="alternate" hreflang="fi" href="https://esirioneyibo.github.io/"><link rel="alternate" hreflang="en" href="https://esirioneyibo.github.io/en.html"><meta property="og:type" content="website"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(description)+'"><meta property="og:url" content="https://esirioneyibo.github.io/'+path+'"><meta property="og:image" content="https://esirioneyibo.github.io/img/social-card.png"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="css/portfolio.css"></head><body>'
for fi in [True,False]:
 lang='fi' if fi else 'en'; path='index.html' if fi else 'en.html'
 labels=['Tietoa','Osaaminen','Projektit','Kokemus','Koulutus','Yhteystiedot'] if fi else ['About','Skills','Projects','Experience','Education','Contact']
 ids=['about','skills','projects','experience','education','contact']
 title='James Oneyibo | '+('Ohjelmistokehittäjä & automaatioinsinööri' if fi else d['title'])
 s=head(lang,title,'Ohjelmistokehitys, automaatio ja käytännön digitaaliset ratkaisut. James Oneyibo, Suomi.' if fi else d['intro'],'' if fi else path)
 s+='<a class="skip" href="#main">'+('Siirry sisältöön' if fi else 'Skip to content')+'</a><header class="site-header"><a class="brand" href="'+path+'"><span class="brand-mark">JO<span>.</span></span> James Oneyibo</a><nav aria-label="'+('Päänavigaatio' if fi else 'Main navigation')+'">'+''.join('<a href="#'+i+'">'+l+'</a>' for i,l in zip(ids,labels))+'</nav><a class="language" href="'+('en.html' if fi else 'index.html')+'" lang="'+('en' if fi else 'fi')+'">'+('English' if fi else 'Suomi')+'</a></header>'
 headline='Ideoista käytännön digitaalisia ratkaisuja.' if fi else d['headline']
 intro='Olen automaatioinsinööri, itseoppinut ohjelmistokehittäjä ja teknologiayrittäjä Suomessa. Vuodesta 2013 olen oppinut, suunnitellut ja rakentanut ratkaisuja verkkokehityksen, mobiilisovellusten, taustajärjestelmien, automaation ja tekoälyavusteisten järjestelmien parissa.' if fi else d['intro']
 s+='<main id="main"><section class="hero"><div><p class="eyebrow">FINLAND / SOFTWARE / AUTOMATION</p><p class="hero-title">'+('Ohjelmistokehittäjä & automaatioinsinööri' if fi else d['title'])+'</p><h1>'+esc(headline)+'</h1><p class="lead">'+esc(intro)+'</p><p class="secondary">'+esc(d['secondary'])+'</p><div class="actions"><a class="button" href="#projects">'+('Tutustu projekteihin' if fi else 'Explore my work')+' ↗</a><a class="button outline" href="resume.html">'+('Ansioluettelo / Resume' if fi else 'View resume')+'</a></div></div><aside class="hero-aside"><span class="eyebrow">JAMES ONEYIBO</span><div class="monogram" aria-hidden="true">J<span>O</span></div><p>Engineering foundation.<br>Software mindset.<br>Human perspective.</p><span class="location">Valkeakoski · Finland</span></aside></section>'
 stats=['13+ vuotta itsenäistä ohjelmistokehitystä ja oppimista','9 dokumentoitua teknologiaprojektia, myös konsepteja','1 julkaistu Android-tuote','EN / FI tuotekehitys ja lokalisointi'] if fi else ['13+ years of independent development & learning','9 documented technology projects, including concepts','1 confirmed launched Android product','EN / FI product development & localization']
 s+='<div class="stats">'+''.join('<p>'+esc(x)+'</p>' for x in stats)+'</div>'
 about=['Olen monialainen ohjelmistokehittäjä ja automaatioinsinööri, jota motivoivat teknologia, yrittäjyys ja käytännön ongelmanratkaisu.','Valmistuin sähkö- ja automaatiotekniikasta vuonna 2013 ja aloitin itsenäisen ohjelmistokehityksen opiskelun. HTML, CSS ja verkkosuunnittelu laajenivat Pythoniin, Ruby on Railsiin, Flutteriin, React Nativeen, Next.js:ään, tietokantoihin ja pilvijulkaisuun.','Olen työskennellyt logistiikka-alustojen, liiketoimintasovellusten, algoritmisten kaupankäyntijärjestelmien, mobiilisovellusten ja automaatiotyökalujen parissa. Perustin Nadarunsin yhdistämään vapaan kuljetuskapasiteetin toimituksia tarvitseviin yrityksiin.','Taustaani kuuluu teollisuustyötä, terveydenhuollon opintoja ja käytännön kokemusta, nuorisopalveluita sekä varhaiskasvatusta. Haluan rakentaa hyödyllisiä, luotettavia ja saavutettavia tuotteita ihmisten ja yritysten tarpeisiin.'] if fi else d['about']
 sections=[para(about)+'<p class="muted">'+('Kielet: englanti (äidinkieli), suomi: suullinen hyvä, kirjallinen tyydyttävä. Vapaa-ajalla vapaaehtoistoimintaa sekä ulkoilua ja retkeilyä perheen kanssa.' if fi else 'Languages: English (native); Finnish: good spoken, satisfactory written. Outside technology: volunteering, outdoor activities and hiking with family.')+'</p>'+tags(d['strengths']),'<div class="grid skills">'+skills()+'</div>','<p class="section-intro">'+('Julkaistut tuotteet, kehitysprojektit ja konseptit on merkitty erikseen. Projektikuvitukset ovat paikkamerkkejä. Projektien tekniset kuvaukset ovat englanniksi.' if fi else 'Launched products, work in progress and concepts. Project identity artwork is a placeholder, not a product screenshot.')+'</p><div class="grid projects">'+projects(fi)+'</div>','<div class="timeline">'+experience()+'</div>','<div class="grid">'+education()+'</div>','<div class="contact-panel"><h3>'+('Rakennetaan jotain hyödyllistä.' if fi else 'Let’s build something useful.')+'</h3><p>'+('Ohjelmistokehitys, freelance-projektit, kumppanuudet ja yhteistyö.' if fi else 'Software development opportunities, freelance projects, business partnerships and collaboration.')+'</p><div class="actions"><a class="button" href="mailto:esirioneyibo@gmail.com">esirioneyibo@gmail.com ↗</a><a href="https://github.com/esirioneyibo">GitHub ↗</a><a href="tel:+358456726453">+358 45 672 6453</a></div><p class="muted">Valkeakoski, Finland</p></div>']
 for num,(i,l,content) in enumerate(zip(ids,labels,sections),1):
  s+='<section class="section" id="'+i+'"><div class="section-heading"><span class="eyebrow">0'+str(num)+' /</span><h2>'+l+'</h2></div>'+content+'</section>'
 s+='</main><footer><span>© 2026 James Oneyibo</span><a href="resume.html">Resume</a><a href="#main">'+('Takaisin ylös' if fi else 'Back to top')+' ↑</a></footer></body></html>\n'
 (ROOT/path).write_text(s.replace('><', '>\n<'))
s=head('en','James Oneyibo | Professional Resume',d['title'],'resume.html')
s+='<header class="resume-header"><a href="en.html">← Portfolio</a><a href="resume.pdf" download>Download PDF resume</a><a href="resume.txt" download>Download text resume</a><button type="button" id="print-resume">Print / Save as PDF</button></header><main class="resume"><h1>'+d['name']+'</h1><p class="lead">'+d['title']+'</p><p>'+d['secondary']+'</p><p>Valkeakoski, Finland · <a href="mailto:esirioneyibo@gmail.com">esirioneyibo@gmail.com</a> · <a href="tel:+358456726453">+358 45 672 6453</a> · <a href="https://github.com/esirioneyibo">GitHub</a></p><h2>Profile</h2>'+para(d['about'])+'<h2>Technical skills</h2>'+skills()+'<h2>Projects</h2>'+projects()+'<h2>Experience</h2>'+experience()+'<h2>Education</h2>'+education()+'<h2>Strengths</h2>'+tags(d['strengths'])+'<h2>Languages & interests</h2><p>English: native. Finnish: good spoken, satisfactory written. English/Finnish product development and localization. Volunteering, outdoor activities and hiking with family.</p></main><script src="js/resume.js" defer></script></body></html>'
(ROOT/'resume.html').write_text(s.replace('><', '>\n<'))
lines=[d['name'],d['title'],d['secondary'],'Valkeakoski, Finland | esirioneyibo@gmail.com | +358 45 672 6453','https://github.com/esirioneyibo','PROFILE',*d['about'],'TECHNICAL SKILLS']
lines += [k+': '+', '.join(v) for k,v in d['skills'].items()]
lines+=['PROJECTS']
for p in d['projects']: lines += [p[0]+' | '+p[1]+' | '+p[2],p[3],', '.join(p[4]),*p[5],*[label+': '+url for label,url in p[6]]]
lines+=['EXPERIENCE',*[' | '.join(x) for x in d['experience']],'EDUCATION',*[' | '.join(x) for x in d['education']],'STRENGTHS',', '.join(d['strengths']),'LANGUAGES & INTERESTS','English: native. Finnish: good spoken, satisfactory written. English/Finnish product localization. Volunteering, outdoor activities and hiking with family.']
(ROOT/'resume.txt').write_text('\n\n'.join(x for x in lines if x)+'\n')
print('Generated index.html, en.html, resume.html, resume.txt')
